 const donut=(rows,title)=>{const top=rows.slice(0,8),tot=rows.reduce((a,r)=>a+r[1],0);let cum=0;const segments=top.map(([k,n],i)=>{const start=cum;cum+=n/Math.max(1,tot)*100;return `${palette[i%palette.length]} ${start}% ${cum}%`});if(cum<100)segments.push(`#dce5ed ${cum}% 100%`);return `<section class="pc-an-card"><h3>${E(title)}</h3><div class="pc-an-donutrow"><div class="pc-an-donut" style="background:conic-gradient(${segments.join(',')||'#e4eaf0 0% 100%'})"><div><strong>${tot}</strong><small>Records</small></div></div><div class="pc-an-legend">${top.map(([k,n],i)=>`<div><i style="background:${palette[i%palette.length]}"></i><span>${E(k)}</span><b>${n} (${tot?Math.round(n/tot*100):0}%)</b></div>`).join('')}</div></div></section>`};
