  const openTickets=sample.filter(r=>!['resolved','closed','completed','won'].includes(String(r.AnalysisStageStatus||r.Status||'').toLowerCase())),inactive=openTickets.filter(r=>age(r)!==null&&age(r)>30),dropped=openTickets.filter(r=>age(r)!==null&&age(r)>90),overdue=openTickets.filter(r=>{const d=day(r.DueDate);return d!==null&&d<today&&!/closed|resolved|completed|solved/i.test(String(r.Status||''))});
