async function moreStage(key){const col=salesColumns.find(c=>String(c.stage?.Id||'')===String(key));if(!col)return;const button=root.querySelector(`[data-action="more-stage"][data-stage="${key}"]`);if(button)button.disabled=true;try{const x=await api('list',{entity,page:col.page+1,size:30,field:stageInfo()[1],value:key,search,owner,from,to,line,project});col.page++;for(const r of x.items)if(!col.items.some(old=>old.Id===r.Id))col.items.push(r);items=salesColumns.flatMap(c=>c.items);root.querySelector('.pc-results').innerHTML=salesBoard()+`<div class="pc-pagination">${total} matching records</div>`;bindDrag();bindCardMoves()}catch(e){if(button)button.disabled=false;error(e)}}
