async function binding(){const d=dialog('Sales Plan · Document binding');d.querySelector('[data-action=close]').onclick=()=>d.remove();const err=x=>error(x,d.querySelector('[data-error]'));try{let x=await api('binding');const b=d.querySelector('.pc-dialog-body');b.innerHTML=`<p>Enable automatic lead creation from approved sales documents. Documents connected by source ID share one lead. Existing customer and staff IDs provide exact links.</p><p>New approved documents generate leads when Biomed IS is saved. Use Sync now to import existing documents. Documents with unmapped owners are skipped.</p><form class="pc-form"><label><input type="checkbox" name="enabled" ${x.config.enabled?'checked':''}> Enable automatic binding</label><fieldset><legend>Document types</legend>${['quotation','customer-order','sales-order','invoice'].map(k=>`<label><input type="checkbox" name="kinds" value="${k}" ${x.config.kinds.includes(k)?'checked':''}> ${E(k)}</label>`).join('')}</fieldset><h3>Employee mapping</h3><p>Shared Staff Portal IDs link automatically. Map other Biomed IS owner names below.</p>${x.sourceOwners.map(o=>`<label>Biomed IS owner: ${E(o||"(not assigned)")}<select data-owner="${E(o)}"><option value="">Use shared ID / skip if unmatched</option>${x.staff.map(u=>`<option value="${E(u.id)}" ${x.config.ownerMap[o]===u.id?"selected":""}>${E(u.name)} (${E(u.id)})</option>`).join("")}</select></label>`).join("")}<div class="pc-actions"><button class="p-btn">Save binding</button>${btn('Sync now','sync')}</div><p data-result role="status"></p></form>`;const form=b.querySelector('form'),out=b.querySelector('[data-result]');form.onsubmit=async ev=>{ev.preventDefault();try{const cfg={enabled:form.elements.enabled.checked,kinds:[...form.querySelectorAll('[name=kinds]:checked')].map(el=>el.value),ownerMap:Object.fromEntries([...form.querySelectorAll('[data-owner]')].filter(el=>el.value).map(el=>[el.dataset.owner,el.value]))};x=await api('binding',{}, {config:cfg,revision:x.revision});out.textContent=JSON.stringify(x.result);await load()}catch(e){err(e)}};b.querySelector('[data-action=sync]').onclick=async()=>{try{out.textContent=JSON.stringify(await api('sync',{},{}));await load()}catch(e){err(e)}}}catch(e){err(e)}}
async function incentive(){const d=dialog('Sales Plan · Incentive-linked targets');d.querySelector('[data-action=close]').onclick=()=>d.remove();const err=x=>error(x,d.querySelector('[data-error]'));try{const rows=await api('schemes');d.querySelector('.pc-dialog-body').innerHTML=`<p>Link only when actual achievement reaches at least 100% of a positive target. Eligibility is recalculated on the server using the same approved-invoice data as Incentive schemes. Linked targets record the achievement at the time of linking.</p><div class="pc-table"><table><thead><tr><th>Representative / product line</th><th>Period</th><th>Target / actual</th><th>Attainment</th><th>Link</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${E(s.rep)} · ${E(s.line)}</td><td>${E(s.from)} – ${E(s.to)}</td><td>${money(s.target)} / ${money(s.actual)}</td><td>${s.attainment.toFixed(1)}%</td><td>${btn(s.linkedId?'Refresh linked target':'Link target','link',`data-scheme="${E(s.id)}" ${!s.eligible||!can('Targets','create')?'disabled':''}`)}</td></tr>`).join('')||'<tr><td colspan="5">No schemes in your reporting scope.</td></tr>'}</tbody></table></div>`;d.querySelectorAll('[data-scheme]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('link-target',{}, {schemeId:b.dataset.scheme});b.textContent='Linked';lookups={};await load()}catch(e){err(e);b.disabled=false}})}catch(e){err(e)}}
async function exportCSV(){const rows=[];let p=1;while(true){const x=await api('list',{entity,page:p,size:100,search,...(hasRecordDates()?{from,to}:{}),owner,project,line,...(field?{field,value}:{})});rows.push(...x.items);if(p*100>=x.total)break;p++}const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(k=>!k.startsWith('_'));const cell=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=entity+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
